import numpy as np, json
def solve(D):
    D=np.array(D); H,W=D.shape
    sr=[i for i in range(H) if np.all(D[i]==8)]
    sc=[j for j in range(W) if np.all(D[:,j]==8)]
    Rb=[]; prev=-1
    for s in sorted(set(sr)|{H}):
        if s>prev+1: Rb.append((prev+1,s-1)); prev=s
    Cb=[]; prev=-1
    for s in sorted(set(sc)|{W}):
        if s>prev+1: Cb.append((prev+1,s-1)); prev=s
    def rband(r): return next(b for b in Rb if b[0]<=r<=b[1])
    def cband(c): return next(b for b in Cb if b[0]<=c<=b[1])
    O=D.copy()
    marks={}
    for r in range(H):
        for c in range(W):
            v=int(D[r][c])
            if v not in (0,8): marks.setdefault(v,[]).append((r,c))
    claim={}
    for v,cells in marks.items():
        cells=set(cells)
        rs={r for r,_ in cells}; cs={c for _,c in cells}
        if len(rs)==1:  # horizontal line: fill rowband between minc..maxc
            r0=list(rs)[0]; rb=rband(r0)
            minc=min(cs); maxc=max(cs)
            for b in Cb:
                lo,hi=b
                if minc<=lo and hi<=maxc:
                    for c in range(lo,hi+1):
                        if c not in set(sc) and (rb,c) not in cells:
                            claim.setdefault((rb,c),[]).append(('H',v))
        elif len(cs)==1:  # vertical line
            c0=list(cs)[0]; cb=cband(c0)
            minr=min(rs); maxr=max(rs)
            for b in Rb:
                lo,hi=b
                if minr<=lo and hi<=maxr:
                    for r in range(lo,hi+1):
                        if r not in set(sr) and (r,cb) not in cells:
                            claim.setdefault((r,cb),[]).append(('V',v))
        else:  # scattered: each marker fills its own band, both directions? use V only; test
            for (r,c) in cells:
                cb=cband(c); rb=rband(r)
                for rr in range(H):
                    if rr not in set(sr) and (rr,c) not in cells:
                        claim.setdefault((rr,cb),[]).append(('V',v))
    for (r,b),modes in claim.items():
        vs={m for m,_ in modes}
        if len(vs)>1: O[r][b]=6
    return [[int(x) for x in row] for row in O.tolist()]
print([solve(G[k+' input'])==G[k+' output'] for k in ['Demo pair 1','Demo pair 2','Demo pair 3']])
